import type { Localized } from './challenges';
import { hbm4AdvancedReferences, hbm4AdvancedSpecs, type LabReference } from './hbm4-advanced-specs';

export type PortInfo = { name: string; direction: string; width: string };
export type TimingExample = { cycle: string; drive: Localized; expect: Localized };
export type LabSpec = {
  purpose: Localized;
  clocking: Localized;
  ports: Record<string, Localized>;
  algorithm: Localized[];
  priority: Localized[];
  example: TimingExample[];
  assumptions: Localized[];
};

const b = (zh: string, en: string): Localized => ({ zh, en });
const e = (cycle: string, zhDrive: string, enDrive: string, zhExpect: string, enExpect: string): TimingExample => ({ cycle, drive: b(zhDrive, enDrive), expect: b(zhExpect, enExpect) });
const spec = (purpose: Localized, clocking: Localized, ports: Record<string, Localized>, algorithm: Localized[], example: TimingExample[], priority: Localized[] = [], assumptions: Localized[] = []): LabSpec => ({ purpose, clocking, ports, algorithm, priority, example, assumptions });

const syncClock = b('所有狀態在 clk 上升緣更新；rst_n 是同步低有效 reset。組合輸出由「目前狀態」計算。', 'All state updates on the rising edge of clk; rst_n is a synchronous active-low reset. Combinational outputs use current state.');
const combinational = b('純組合模組：輸入改變後，同一模擬時間步內輸出必須穩定；沒有 clock 或內部狀態。', 'Purely combinational: outputs settle in the same simulation time step after inputs change; there is no clock or internal state.');
const resetPorts = { clk: b('模組時脈；只在上升緣提交狀態。', 'Module clock; state commits only on rising edges.'), rst_n: b('同步低有效 reset；在 clk 上升緣為 0 時清除所有狀態。', 'Synchronous active-low reset; clears all state when low at a rising edge.') };

