    [b('Completion fill 使用 tag；retirement 永遠只使用 issue-order head。', 'Completion fill uses tags; retirement always uses the issue-order head.')], [b('本題不處理 unknown tag error、split completion 或同拍複雜 bypass；產品需擴充。', 'This lab omits unknown-tag errors, split completions, and complex same-cycle bypass; products must extend it.')],
